{
  "vulnerable_symbols": [
    "_.unset",
    "_.omit"
  ],
  "trigger": "当外部可控的 path/paths 参数传入 _.unset 或 _.omit，且包含数组包装的原型路径片段（如 [['__proto__'], 'key']）时，可删除内置原型属性。",
  "preconditions": [
    "使用受影响版本 lodash（<=4.17.23，修复前）"
  ],
  "exploit_evidence": [],
  "fixed_version": "4.18.1",
  "summary_zh": "lodash 的 _.unset/_.omit 可被数组路径绕过原型保护，删除内置原型属性，造成逻辑异常或 DoS，请升级。"
}
